    "dataSources": {
        "ds_health": {
            "type": "ds.searchbase",
            "name": "Secure Data Center - ACI Fabric Health Score",
            "options": {
                "ref": "secure_data_center_aci_fabric_health_score",
                "queryParameters": {
                    "earliest": "$time_tok.earliest$",
                    "latest": "$time_tok.latest$"
                }
            }
        },
        "ds_anomalies": {
            "type": "ds.searchbase",
            "name": "Secure Data Center - ACI Critical and Major Fault Count",
            "options": {
                "ref": "secure_data_center_aci_critical_fault_count",
                "queryParameters": {
                    "earliest": "$time_tok.earliest$",
                    "latest": "$time_tok.latest$"
                }
            }
        },
        "ds_advisories": {
            "type": "ds.searchbase",
            "name": "Secure Networking - DC Security Advisory Count",
            "options": {
                "ref": "secure_networking_dc_advisory_count",
                "queryParameters": {
                    "earliest": "$time_tok.earliest$",
                    "latest": "$time_tok.latest$"
                }
            }
        },
        "ds_interfaces": {
            "type": "ds.searchbase",
            "name": "Secure Networking - DC Interface Anomaly Count",
            "options": {
                "ref": "secure_networking_dc_interface_anomaly_count",
                "queryParameters": {
                    "earliest": "$time_tok.earliest$",
                    "latest": "$time_tok.latest$"
                }
            }
        },
        "ds_port_utilization": {
            "type": "ds.searchbase",
            "name": "Secure Data Center - ACI Peak Port Utilization",
            "options": {
                "ref": "secure_data_center_aci_port_utilization_trend",
                "queryParameters": {
                    "earliest": "$time_tok.earliest$",
                    "latest": "$time_tok.latest$"
                }
            }
        },
        "ds_changes": {
            "type": "ds.searchbase",
            "name": "Secure Networking - DC ACI Configuration Change Count",
            "options": {
                "ref": "secure_networking_dc_aci_configuration_change_count",
                "queryParameters": {
